import { SbSession, sbSessionHere } from '../helpers/supabase';

export const authPath = (id: string) => path.resolve(__dirname, '../../../auth', `${id}.json`);

/**
 * Данные, которые МОЖНО блокировать (только они, больше никого — см. .qa/research/_admin-testdata.md).
 * SIGNUP14A: компания «QA add75b בע"מ» с единственным מנהל חשבון qa-add75b-34a884ea@… (в списке есть ТЁЗКА — SIGNUP14, её трогать нельзя).
 * INV14: «QA Inv14 Member» qa-inv14-62d78ddb@…, משתמש רגיל компании «QA Company B» (компанию B не блокируем).
 */
export const TARGET = {
  companyId: '0307264e-34e1-4b49-b559-bc8201f6eaa2',
  companyNameFilter: 'QA add75b',
  companyMemberEmail: 'qa-add75b-34a884ea',
  userId: '6ab697c0-be29-49e8-9291-64c4810ebe71',
  userEmail: 'qa-inv14-62d78ddb',
};

/** Окно роли с сохранённой сессией, параметры (адрес, язык, размер) — из текущего проекта Playwright. */
export async function openRoleContext(browser: Browser, testInfo: TestInfo, id: string): Promise<BrowserContext> {
  const u = testInfo.project.use as Record<string, any>;
  return browser.newContext({
    baseURL: u.baseURL,
    locale: u.locale,
    viewport: u.viewport ?? undefined,
    storageState: authPath(id),
  });
}

export const dialogOf = (page: Page) => page.getByRole('dialog').or(page.getByRole('alertdialog')).first();
export const companiesTable = (page: Page) => page.locator('table').first();
export const usersTable = (page: Page) => page.locator('table').nth(1);
export const rowsOf = (table: Locator) => table.locator('tbody tr');
export const companiesHeading = (page: Page) => page.getByRole('heading', { name: /^חברות \(\d+\)$/ });
export const usersHeading = (page: Page) => page.getByRole('heading', { name: /^משתמשים \(\d+\)$/ });
export const searchBox = (page: Page) => page.getByPlaceholder('חיפוש חברה או משתמש…');

/** Число из заголовка «חברות (N)» / «משתמשים (N)». */
export async function countIn(heading: Locator): Promise<number> {
  const m = (await heading.innerText()).match(/\((\d+)\)/);
  expect(m, 'в заголовке должно быть число в скобках').not.toBeNull();
  return Number(m![1]);
}

/** Открыть /admin и дождаться обеих таблиц с данными. */
export async function openAdmin(page: Page) {
  await page.goto('/admin');
  await expect(page.getByRole('heading', { name: 'ניהול חברות ומשתמשים', level: 1 })).toBeVisible();
  await expect(companiesHeading(page)).toBeVisible();
  await expect(usersHeading(page)).toBeVisible();
  await expect(rowsOf(companiesTable(page)).first()).toBeVisible();
}

/** Запросы, которые что-то меняют на сервере (кроме входа и чтения списков). Список пуст = экран ничего не изменил. */
export function trackMutations(page: Page) {
  const reqs: string[] = [];
  page.on('request', (r) => {
    const url = r.url();
    if (['GET', 'HEAD', 'OPTIONS'].includes(r.method())) return;
    if (!/supabase\.co/.test(url) || /\/auth\/v1\//.test(url) || /rpc\/platform_list_/.test(url)) return;
    reqs.push(`${r.method()} ${url.replace(/^.*supabase\.co/, '')}`);
  });
  return reqs;
}

/** Вызов RPC Supabase от имени роли сессии. */
export async function sbRpc(s: SbSession, name: string, body: Record<string, unknown> = {}) {
  const res = await s.page.request.post(`${s.url}/rest/v1/rpc/${name}`, {
    headers: { apikey: s.apiKey, Authorization: `Bearer ${s.token}`, 'Content-Type': 'application/json' },
    data: body,
  });
  const text = await res.text();
  let json: any = null;
  try { json = JSON.parse(text); } catch { /* не JSON */ }
  return { status: res.status(), text, json };
}

/** Сессия platform на странице /admin (без перехода на «/»: у platform нет компании). */
export async function platformSession(page: Page): Promise<SbSession> {
  if (!/\/admin/.test(page.url())) await page.goto('/admin');
  return sbSessionHere(page);
}

/**
 * Страховочное снятие блокировок с тестовых данных (SIGNUP14A-компания и INV14), независимо от интерфейса.
 * Вызывается в начале и в finally/afterAll блокирующих тестов. Только эти два id.
 */
export async function unblockTargets(page: Page) {
  const s = await platformSession(page);
  const a = await sbRpc(s, 'platform_set_company_suspended', { p_company: TARGET.companyId, p_suspended: false });
  const b = await sbRpc(s, 'platform_set_user_blocked', { p_user: TARGET.userId, p_blocked: false });
  expect(a.status, `снятие блокировки компании: ${a.text}`).toBeLessThan(300);
  expect(b.status, `снятие блокировки пользователя: ${b.text}`).toBeLessThan(300);
}

/** Строка компании SIGNUP14A: из двух «QA add75b» — та, у которой при «פתיחה» виден участник qa-add75b-34a884ea. Компания остаётся открытой. */
export async function findSignup14aCompanyRow(page: Page): Promise<Locator> {
  const rows = rowsOf(companiesTable(page)).filter({ hasText: TARGET.companyNameFilter });
  const n = await rows.count();
  expect(n, 'ожидались компании-тёзки «QA add75b»').toBeGreaterThanOrEqual(1);
  for (let i = 0; i < n; i++) {
    const row = rows.nth(i);
    await row.getByRole('button', { name: 'פתיחה', exact: true }).click();
    const member = usersTable(page).locator('tbody tr').filter({ hasText: TARGET.companyMemberEmail });
    if ((await member.count()) === 1) return row;
    await row.getByRole('button', { name: 'סגירה', exact: true }).click();
  }
  throw new Error('Не найдена компания SIGNUP14A (участник qa-add75b-34a884ea) — блокировка отменена');
}

/** Подтвердить действие в диалоге «אישור פעולה»: подтверждающая кнопка — последняя (первая — «ביטול»). */
export async function confirmDialog(page: Page, buttonName: 'חסימה' | 'ביטול חסימה') {
  const dlg = dialogOf(page);
  await expect(dlg.getByText('אישור פעולה', { exact: true })).toBeVisible();
  await dlg.getByRole('button', { name: buttonName, exact: true }).click();
  await expect(dlg).toBeHidden();
}
